import {
  hasTranscriptShellMarkup,
  installTranscriptDialogMarkup,
  installTranscriptShellMarkup,
  installTranscriptTriggerMarkup,
  removeTranscriptDialogMarkup,
  removeTranscriptShellMarkup,
  TRANSCRIPT_TRIGGER_CONTROLS_HTML,
  TRANSCRIPT_UPLOAD_DIALOG_REF,
  TRANSCRIPT_WARNING_REF,
} from './html/install-shell-markup.ts';
import transcriptCssUrl from './transcript.scss?url';
import { olEditorTranscriptPluginData } from './transcript_ol_editor.ts';
import type {
  OpenLyricComponentHost,
  OpenLyricContributions,
  OpenLyricPlugin,
  OpenLyricSurface,
} from '../../editor/components/index.ts';
import { queryRef } from '../../editor/html/markup-fragments.ts';
import { EditorPreferencesStore } from '../../editor/scripts/app/EditorPreferencesStore.ts';
import {
  getRegisteredTranscriptSpecifications,
  registerPlugin,
  unregisterPlugin,
} from '../../editor/scripts/editor-plugin-registry.ts';
import { refreshElementRefs } from '../../editor/scripts/shared.ts';

/**
 * The transcript plugin expressed in the generic per-component contract from
 * `research/editor-structure-implemented.md` (§"Example: the transcript
 * plugin"). All contribution data is the real registry data
 * (`transcript_ol_editor.ts`) — the same `createTranscriptController`
 * factory, action label, and CSS the application consumes.
 *
 * Page chrome and plugin composition are two independent axes, exactly as for
 * the surface classes: {@link EditorPluginTranscript.installShellMarkup} is
 * the ONLY thing that puts transcript markup on a page shell, and attaching
 * the plugin is what makes that markup do something. A page entry that
 * composes the plugin without calling the static gets the feature registered
 * and no UI — every ref the controller drives stays null, and the controller
 * guards each one, so it simply sits inert.
 *
 * `install()` (runs synchronously from `addPlugin()`, before any boot):
 * publishes the registry data through the GLOBAL plugin registry, so a
 * wrapped application (the app pages) creates its transcript controller
 * during boot. The dashboard no longer registers transcript as a built-in —
 * composing this plugin is the only thing that enables it (singleton-guarded:
 * with a spec already registered this instance owns nothing). It installs no
 * markup: a page that did not ask for the chrome does not get it.
 *
 * `onMount()` (standalone `Editor` only — wrap-phase facades keep plugins
 * dormant, so this never runs on the app pages): mounts the record/upload
 * flow for real. The trigger controls — built from the SAME
 * `trigger-controls.html` fragment, adapted for a bare host — go into the
 * standalone chrome's toolbar, the dialogs get a home on the chrome panel
 * when no page copy exists, and the real transcript controller runs against
 * the component's Monaco surface with a locally built context (refs bag,
 * live editor-mode view, `EditorPreferencesStore`). Monaco-only, like a
 * language plugin's keyboard: the textarea fallback and `chrome: false`
 * hosts keep the declarative contributions but mount no flow.
 */

export interface EditorPluginTranscriptOptions {
  /**
   * Transcription backend. Today's implementation is browser-direct
   * ElevenLabs — the API key is entered by the user at runtime and kept in
   * local storage; no server is involved.
   */
  provider?: 'elevenlabs';
  /**
   * Where the browser-warning banner goes when a STANDALONE mount has to
   * install it (`onMount()` — a bare `Editor` on a page that called no
   * `installShellMarkup()`). Omit it and the banner takes a fixed-position
   * toast panel the plugin creates at the bottom of the viewport, so a host
   * with nowhere to put it still gets one.
   *
   * This is the standalone counterpart of the same option on
   * {@link EditorPluginTranscript.installShellMarkup}, which is what a page
   * shell uses to place its own chrome. An instance never installs page
   * chrome, so on the app pages this option does nothing.
   */
  container?: HTMLElement | null;
}

interface TranscriptControllerLike {
  destroy?: () => void;
  syncHostUi?: () => void;
}

/** Duck-typed view of the standalone `Editor` this plugin mounts on. */
interface StandaloneEditorHostLike {
  monacoEditor?: unknown;
  monacoNamespace?: unknown;
  surfaceKind?: string;
  undo?: () => void;
  redo?: () => void;
}

/**
 * Marker class the standalone mount stamps on dialogs it installs outside a
 * dashboard, activating the plugin's own base dialog styling
 * (`transcript.scss`) where `styles/dialogs.scss` never loads.
 */
const TRANSCRIPT_STANDALONE_DIALOG_CLASS = 'editor-transcript--standalone';

/**
 * Bootstrap-icon glyphs, inlined as SVG the way the standalone chrome inlines
 * its own (`EditorStandaloneChrome`), so the trigger controls need no icon
 * webfont on a bare host page.
 */
const ICONS = {
  mic: '<svg viewBox="0 0 16 16" fill="currentColor" aria-hidden="true"><path d="M5 3a3 3 0 0 1 6 0v5a3 3 0 0 1-6 0z"/><path d="M3.5 6.5A.5.5 0 0 1 4 7v1a4 4 0 0 0 8 0V7a.5.5 0 0 1 1 0v1a5 5 0 0 1-4.5 4.975V15h3a.5.5 0 0 1 0 1h-7a.5.5 0 0 1 0-1h3v-2.025A5 5 0 0 1 3 8V7a.5.5 0 0 1 .5-.5"/></svg>',
  upload:
    '<svg viewBox="0 0 16 16" fill="currentColor" aria-hidden="true"><path d="M.5 9.9a.5.5 0 0 1 .5.5v2.5a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1v-2.5a.5.5 0 0 1 1 0v2.5a2 2 0 0 1-2 2H2a2 2 0 0 1-2-2v-2.5a.5.5 0 0 1 .5-.5"/><path d="M7.646 1.146a.5.5 0 0 1 .708 0l3 3a.5.5 0 0 1-.708.708L8.5 2.707V11.5a.5.5 0 0 1-1 0V2.707L5.354 4.854a.5.5 0 1 1-.708-.708z"/></svg>',
} as const;

interface StandaloneTriggerControls {
  root: HTMLElement;
  localeSelect: HTMLSelectElement;
  uploadButton: HTMLButtonElement;
  toggleButton: HTMLButtonElement;
  status: HTMLElement;
}

/**
 * Build the standalone copy of the trigger controls from the SAME fragment
 * the app shell installs (`html/trigger-controls.html`) — one markup source,
 * two shells. Two standalone adaptations: the bootstrap-icons `<i class="bi">`
 * glyphs become inline SVG (the standalone chrome ships no icon webfont), and
 * every `data-ol-ref` handle is stripped — these elements are private to the
 * standalone controller's refs bag, never part of the app's captured refs.
 */
function buildTriggerControls(
  ownerDocument: Document,
): StandaloneTriggerControls | null {
  const template = ownerDocument.createElement('template');
  template.innerHTML = TRANSCRIPT_TRIGGER_CONTROLS_HTML.trim();
  const root = template.content.firstElementChild;
  if (!(root instanceof HTMLElement)) {
    return null;
  }

  const localeSelect = root.querySelector<HTMLSelectElement>(
    '[data-ol-ref="editorTranscriptLocaleSelect"]',
  );
  const uploadButton = root.querySelector<HTMLButtonElement>(
    '[data-ol-ref="editorTranscriptUploadBtn"]',
  );
  const toggleButton = root.querySelector<HTMLButtonElement>(
    '[data-ol-ref="editorTranscriptToggleBtn"]',
  );
  const status = root.querySelector<HTMLElement>(
    '[data-ol-ref="editorTranscriptStatus"]',
  );
  if (!localeSelect || !uploadButton || !toggleButton || !status) {
    return null;
  }

  const uploadIcon = uploadButton.querySelector('.topbar-icon-btn__icon');
  if (uploadIcon) {
    uploadIcon.innerHTML = ICONS.upload;
  }
  const toggleIcon = toggleButton.querySelector('.topbar-icon-btn__icon');
  if (toggleIcon) {
    toggleIcon.innerHTML = ICONS.mic;
  }

  root.removeAttribute('data-ol-ref');
  for (const element of root.querySelectorAll('[data-ol-ref]')) {
    element.removeAttribute('data-ol-ref');
  }

  return { root, localeSelect, uploadButton, toggleButton, status };
}

/**
 * The refs bag the transcript controller drives its UI through — the
 * standalone stand-in for the app's captured `shared.ts` refs. Dialog and
 * banner handles resolve from the document (whoever installed them: this
 * plugin's `install()`, the page-level static, or the standalone mount);
 * the trigger controls are the elements built above; `simpleEditorToggle` is
 * the standalone chrome's mode switch, whose `change` events the controller
 * already listens to for simple ⇄ Monaco resyncs.
 */
function buildStandaloneTranscriptRefs(
  controls: StandaloneTriggerControls,
  modeToggle: HTMLElement | null,
  ownerDocument: Document,
): Record<string, unknown> {
  const documentRefNames = [
    'editorTranscriptBrowserWarning',
    'editorTranscriptDownloadChromeWarning',
    'editorTranscriptUploadDialog',
    'editorTranscriptUploadForm',
    'editorTranscriptUploadFileInput',
    'editorTranscriptUploadApiKeyInput',
    'editorTranscriptUploadLocaleSelect',
    'editorTranscriptUploadMessage',
    'editorTranscriptUploadPermissionTip',
    'editorTranscriptUploadPermissionInstructionBtn',
    'editorTranscriptUploadPermissionDialog',
    'closeEditorTranscriptUploadBtn',
    'closeEditorTranscriptUploadPermissionDialogBtn',
    'submitEditorTranscriptUploadBtn',
  ];
  const refs: Record<string, unknown> = {};
  for (const name of documentRefNames) {
    refs[name] = queryRef(name, ownerDocument);
  }
  refs['editorTranscriptLocaleSelect'] = controls.localeSelect;
  refs['editorTranscriptUploadBtn'] = controls.uploadButton;
  refs['editorTranscriptToggleBtn'] = controls.toggleButton;
  refs['editorTranscriptStatus'] = controls.status;
  refs['simpleEditorToggle'] = modeToggle;
  return refs;
}

class EditorPluginTranscript implements OpenLyricPlugin {
  /**
   * Install the plugin's page-shell chrome — the trigger controls, the
   * browser-warning banner, and the upload + permission dialogs — from a page
   * entry, before any component is composed: the same per-page contract as
   * `Editor.installShellMarkup()`, for plugin-owned chrome instead of a panel.
   *
   * This is the ONLY thing that puts transcript markup on a page shell.
   * Composing the plugin does not imply it and never installs any of this —
   * shell markup and plugin composition are independent opt-ins, so a page
   * entry that wants the feature calls both, and one that wants neither the
   * chrome nor a stray dialog simply omits this call. Markup installed here is
   * page-owned: {@link uninstall} leaves it in place.
   *
   * Targets: the trigger controls take the editor panel's
   * `editorTranscriptControls` mount, the banner takes `container` or the
   * plugin's toast panel, the dialogs take `container` or the dashboard shell
   * root. So on a dashboard page call this after
   * `OpenLyricDashboard.installShellMarkup()` and `Editor.installShellMarkup()`
   * — before the shell root and editor panel exist, the dialogs and trigger
   * controls are skipped — and on a bare page with no `container` only the
   * banner is installed. Idempotent, and refs refresh only when something was
   * actually installed.
   */
  static installShellMarkup(
    options: { container?: HTMLElement | null } = {},
  ): void {
    const container =
      options.container instanceof HTMLElement ? options.container : null;
    const trigger = installTranscriptTriggerMarkup();
    const warning = installTranscriptShellMarkup({ container });
    const dialogs = installTranscriptDialogMarkup({ container });
    if (trigger || warning || dialogs.length) {
      refreshElementRefs();
    }
  }

  readonly id = 'transcript';
  readonly apiVersion = 1 as const;
  readonly surfaces: readonly OpenLyricSurface[] = ['editor', 'dashboard'];
  readonly contributes: OpenLyricContributions;

  readonly provider: 'elevenlabs';

  /** Host element for the browser-warning banner; null means "toast panel". */
  private readonly container: HTMLElement | null;

  /** Same store the application uses, so transcript prefs stay shared. */
  private readonly preferences = new EditorPreferencesStore();

  /**
   * The banner the standalone mount fell back to installing, so `uninstall()`
   * removes only its own — a page-installed banner is never this instance's.
   */
  private warningElement: HTMLElement | null = null;

  /** The global-registry registration this instance owns, if any. */
  private registryRegistration: ReturnType<typeof registerPlugin> | null = null;

  /** The live standalone record/upload flow, mounted in {@link onMount}. */
  private standaloneController: TranscriptControllerLike | null = null;
  private standaloneControls: HTMLElement | null = null;
  /** Dialogs the standalone mount created (a page copy is never removed). */
  private standaloneDialogs: HTMLElement[] = [];

  constructor(options: EditorPluginTranscriptOptions = {}) {
    this.provider = options.provider ?? 'elevenlabs';
    this.container =
      options.container instanceof HTMLElement ? options.container : null;
    this.contributes = {
      // Singleton kind: a component rejects a second transcript plugin.
      transcript: {
        ...olEditorTranscriptPluginData.transcript,
        provider: this.provider,
      },
      style: { href: transcriptCssUrl },
    };
  }

  /**
   * Publish the registry data — the transcript specification + styles go into
   * the GLOBAL plugin registry, which is what a wrapped application consumes
   * when it boots its transcript controller. The dashboard no longer
   * registers transcript as a built-in, so composing this plugin is what
   * enables the feature on the app pages.
   *
   * Deliberately installs no markup, and **demands** that the page already
   * did. The page shell's transcript chrome — the trigger controls, the
   * browser-warning banner, the upload + permission dialogs — belongs to
   * whoever renders the page shell, and the page asks for it by calling
   * {@link installShellMarkup}, the same contract as
   * `Editor.installShellMarkup()` for the editor panel.
   *
   * So the two opt-ins stay separate, but not independent: chrome without the
   * plugin is a page that renders dead controls, and the plugin without chrome
   * is a feature registered with no UI to drive it. The second one used to pass
   * silently — the controller would boot against null refs, guard every one of
   * them, and do nothing at all — so it throws instead. `addPlugin()` rolls the
   * record back on a throwing `install()`, leaving nothing half-attached.
   *
   * That is why every page entry calls the static BEFORE composing the plugin:
   * comment out `EditorPluginTranscript.installShellMarkup()` in
   * `editor/main-editor.ts` and the page fails loudly at
   * `addPlugin('transcript', …)` rather than booting a feature that cannot
   * work. Dropping transcript from a page means dropping both lines.
   *
   * A standalone `Editor` is the one host that still installs chrome from the
   * component itself, in {@link onMount} — a bare page has no shell root for
   * the dialogs, so the static lands only the banner there and the mount fills
   * in the rest. That banner is also what satisfies the demand above, so a
   * standalone page entry calls the static exactly like a dashboard page does.
   *
   * Runs synchronously from `addPlugin()`, i.e. before the dashboard boots.
   *
   * @throws when no transcript shell markup is on the page.
   */
  install(): void {
    if (!hasTranscriptShellMarkup()) {
      throw new Error(
        'addPlugin("transcript", new EditorPluginTranscript()): no transcript ' +
          'shell markup on the page. Call ' +
          'EditorPluginTranscript.installShellMarkup() from the page entry ' +
          'first — after OpenLyricDashboard.installShellMarkup() and ' +
          'Editor.installShellMarkup(), so the dialogs and trigger controls ' +
          'find their hosts. To drop transcript from this page instead, ' +
          'remove the addPlugin() call too.',
      );
    }
    if (getRegisteredTranscriptSpecifications().length === 0) {
      this.registryRegistration = registerPlugin(olEditorTranscriptPluginData);
    }
  }

  uninstall(): void {
    this.teardownStandaloneTranscript();
    removeTranscriptShellMarkup(this.warningElement);
    this.warningElement = null;
    if (this.registryRegistration) {
      unregisterPlugin(this.registryRegistration);
      this.registryRegistration = null;
    }
  }

  /**
   * Standalone mounting: run the real record/upload flow on a bare `Editor`.
   *
   * Only ever called for a component that mounted its own surface — the
   * wrap-phase facade keeps plugins dormant, so the app pages never take this
   * path (their controller is the application's, built from the registry
   * data published in {@link install}). Monaco-only, like a language
   * plugin's keyboard: with the textarea fallback (or no standalone chrome
   * toolbar to put the trigger controls in) nothing mounts.
   */
  onMount(host: OpenLyricComponentHost): void {
    if (host.surface !== 'editor' || this.standaloneController) {
      return;
    }

    const editorHost = host as unknown as StandaloneEditorHostLike;
    const monacoEditor = editorHost.monacoEditor;
    const monaco = editorHost.monacoNamespace;
    const container = host.container;
    if (!monacoEditor || !monaco || !container) {
      return;
    }

    const toolbar = container.querySelector('.editor-panel__toolbar-actions');
    if (!(toolbar instanceof HTMLElement)) {
      return;
    }

    const ownerDocument = container.ownerDocument ?? document;
    const ownerWindow = ownerDocument.defaultView ?? window;

    const controls = buildTriggerControls(ownerDocument);
    if (!controls) {
      return;
    }
    // The app panel's slot: between the copy button and the ⋮ tools menu.
    const optionsElement = toolbar.querySelector('[data-role="options"]');
    toolbar.insertBefore(
      controls.root,
      optionsElement instanceof HTMLElement ? optionsElement : null,
    );
    this.standaloneControls = controls.root;

    // install() had no dashboard shell to hang the dialogs on; give them the
    // chrome panel (falling back to the component container) — inside the
    // theme-variable scope and the panel's Bootstrap shim — marked for the
    // plugin's own standalone dialog styling. A copy already on the page
    // (inlined, or from the page-level static) is reused, never re-mounted.
    if (!queryRef(TRANSCRIPT_UPLOAD_DIALOG_REF, ownerDocument)) {
      const dialogHost =
        toolbar.closest<HTMLElement>('.ol-standalone-editor') ?? container;
      this.standaloneDialogs = installTranscriptDialogMarkup({
        container: dialogHost,
      });
      for (const dialog of this.standaloneDialogs) {
        dialog.classList.add(TRANSCRIPT_STANDALONE_DIALOG_CLASS);
      }
    }
    if (!queryRef(TRANSCRIPT_WARNING_REF, ownerDocument)) {
      this.warningElement = installTranscriptShellMarkup({
        container: this.container,
      });
    }

    const modeToggle = container.querySelector<HTMLElement>(
      '[data-role="mode-toggle"]',
    );

    try {
      this.standaloneController = this.createController({
        // The controller's undo/redo voice commands go through the host
        // application on the app pages; here the component's own history
        // methods are that application.
        application: {
          runEditorHistoryCommand: (command: unknown) => {
            if (command === 'undo') {
              editorHost.undo?.();
            } else if (command === 'redo') {
              editorHost.redo?.();
            }
          },
        },
        editor: monacoEditor,
        monaco,
        onStateChange: () => {},
        ownerDocument,
        ownerWindow,
        preferences: this.preferences,
        refs: buildStandaloneTranscriptRefs(
          controls,
          modeToggle,
          ownerDocument,
        ),
        // Live view of the component's surface, in the shape the controller
        // reads (`state.editorMode === 'monaco'`).
        state: {
          get editorMode() {
            return editorHost.surfaceKind === 'monaco' ? 'monaco' : 'simple';
          },
        },
      });
    } catch (error) {
      console.error('Transcript plugin failed to mount.', error);
      this.teardownStandaloneTranscript();
    }
  }

  onUnmount(): void {
    this.teardownStandaloneTranscript();
  }

  /** True while the standalone record/upload flow is mounted. */
  get isStandaloneTranscriptMounted(): boolean {
    return this.standaloneController !== null;
  }

  /**
   * Build the real transcript controller from the same factory the
   * application uses. The context must supply the editor shell pieces the
   * controller renders into (`editor`, `monaco`, `refs`, `preferences`,
   * `state`, `ownerDocument`/`ownerWindow`, `onStateChange`).
   */
  createController(context: Record<string, unknown>): TranscriptControllerLike {
    return olEditorTranscriptPluginData.transcript.create(
      context,
    ) as TranscriptControllerLike;
  }

  private teardownStandaloneTranscript(): void {
    try {
      this.standaloneController?.destroy?.();
    } catch (error) {
      console.error('Transcript plugin failed to dispose.', error);
    }
    this.standaloneController = null;
    this.standaloneControls?.remove();
    this.standaloneControls = null;
    removeTranscriptDialogMarkup(this.standaloneDialogs);
    this.standaloneDialogs = [];
  }
}

export { EditorPluginTranscript };
